#include <fstream>
#include <iostream>

int main() {
    std::ofstream file1("example1.txt");  // Opens file1
    std::ofstream file2("example2.txt");  // Opens file2
    file1 << "Data in file1";  // Writes to file1's buffer
    file2.swap(file1);  // Swaps resources: file2 now manages example1.txt, and file1 manages example2.txt
    file2 << " Appended data";  // Now writes to what was originally file1
    return 0;  // Files are closed upon destruction
}
